pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, address other, bytes32 hash) public {
        // keep params in the admissible domain (wide)
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(other != address(0) && other != actor && other != address(c));

        uint256 b = block.number;

        // 1. actor locks in the fuzzed hash; the contract stores block b + 1
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // 2. execute a transaction at block b + 1 so that its blockhash exists,
        //    then move past it so settle()'s gate (block.number > stored block) opens
        vm.deal(other, 1 ether);
        vm.roll(b + 1);
        vm.prank(other);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));
        vm.roll(b + 2);

        bytes32 bh = blockhash(b + 1); // the answer settle() will compute

        // 3. single assertion: payout happens exactly when the stored guess (hash)
        //    matches the blockhash of the locked block; if the answer is 0 no one pays
        uint256 bal0 = actor.balance;
        vm.prank(actor);
        try c.settle() {
            bool paid = actor.balance == bal0 + 2 ether;
            assertTrue(bh == bytes32(0) ? !paid : (paid == (hash == bh)));
        } catch {
            assertTrue(bh == bytes32(0) || hash != bh);
        }
    }
}

