pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        uint256 target = block.number; // stored target block
        // Move exactly one block forward: settle is allowed (block.number > target)
        // and blockhash(target) is nonzero (hash of the immediately previous block).
        vm.roll(target + 1);
        bytes32 answer = blockhash(target);
        vm.assume(answer != 0);

        uint256 before = actor.balance;

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 delta = actor.balance - before;

        // General rule: whenever settle() succeeds, the actor walks away with both
        // stakes (2 ether) IF AND ONLY IF the locked hash equals the target block's
        // blockhash. The complement mutant pays out exactly in the opposite case,
        // so it breaks this rule for almost any admissible (actor, h).
        assertTrue(!ok || ((delta == 2 ether) == (h == answer)));
    }
}

