pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(h != ~h);

        vm.roll(block.number + 10);
        uint target = block.number + 1;

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        vm.roll(target + 1);

        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("settle()"));

        bool guessMatches = (blockhash(target) == h);
        bool refPaid = guessMatches && blockhash(target) != 0;

        assertTrue(ok == refPaid, "settle pays iff guess equals target blockhash");
    }
}

