pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        // keep the domain admissible: actor must be a plain fresh EOA able to call
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);

        vm.deal(actor, 2 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 1 ether}(
            abi.encodeWithSelector(c.lockInGuess.selector, h)
        );

        (uint storedBlock, bytes32 storedGuess) = c.guesses(actor);

        // GENERAL RULE: a successful lockInGuess(h) records exactly h as the
        // caller's guess (and a nonzero target block). The mutant stores ~h,
        // which differs from h for every possible h, so it breaks this rule
        // for every admissible input that succeeds.
        assertTrue(ok && storedBlock != 0 && storedGuess == h);
    }
}

