pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h1, bytes32 h2) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(h2) {
            assertTrue(false, "second lock-in must revert: guess cannot be overwritten");
        } catch {
            assertTrue(true);
        }
    }
}

contract InvMutTest {

    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function testLockIn(uint256 amount, bytes32 g) public payable {
        require(address(this).balance >= amount);
        uint256 before = address(c).balance;
        c.lockInGuess{value: amount}(g);
        assert(address(c).balance == before + amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0 && amount < 2 ether);
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(amount))) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount < address(this).balance || true);
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess(bytes32(uint(1))){value: amount} { reverted = false; } catch { reverted = true; }
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
